using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools that wrap a weather REST API.
/// The MCP SDK discovers tools by scanning for [McpServerToolType] classes
/// and [McpServerTool] methods. Constructor parameters are resolved via DI.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection: the MCP host resolves this from the DI container.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get the current weather forecast for a US state.")]
    public async Task<string> GetForecast(
        [Description("Two-letter US state code, e.g. CA, NY")] string state,
        CancellationToken cancellationToken = default)
    {
        // National Weather Service API (no key required)
        var zones = await _httpClient.GetFromJsonAsync<ZoneResponse>(
            $"zones/forecast?area={state}&type=forecast&limit=1",
            cancellationToken);

        if (zones?.Features is not [var zone, ..])
            return $"No forecast zone found for state '{state}'.";

        var forecastUrl = zone.Properties.Forecast;
        var forecast = await _httpClient.GetFromJsonAsync<ForecastResponse>(
            forecastUrl, cancellationToken);

        if (forecast?.Properties.Periods is not [var current, ..])
            return "No forecast periods available.";

        return $"{current.Name}: {current.Temperature}°{current.TemperatureUnit} — {current.DetailedForecast}";
    }

    [McpServerTool, Description("List available weather alert zones for a US state.")]
    public async Task<string> GetAlerts(
        [Description("Two-letter US state code")] string state,
        CancellationToken cancellationToken = default)
    {
        var response = await _httpClient.GetFromJsonAsync<AlertResponse>(
            $"alerts/active?area={state}", cancellationToken);

        if (response?.Features is not { Count: > 0 })
            return $"No active alerts for '{state}'.";

        return string.Join("\n", response.Features.Select(f =>
            $"• {f.Properties.Event}: {f.Properties.Headline}"));
    }

    // --- JSON DTOs for the NWS API ---

    private record ZoneResponse(
        [property: JsonPropertyName("features")] List<ZoneFeature> Features);

    private record ZoneFeature(
        [property: JsonPropertyName("properties")] ZoneProperties Properties);

    private record ZoneProperties(
        [property: JsonPropertyName("forecast")] string Forecast);

    private record ForecastResponse(
        [property: JsonPropertyName("properties")] ForecastProperties Properties);

    private record ForecastProperties(
        [property: JsonPropertyName("periods")] List<ForecastPeriod> Periods);

    private record ForecastPeriod(
        [property: JsonPropertyName("name")] string Name,
        [property: JsonPropertyName("temperature")] int Temperature,
        [property: JsonPropertyName("temperatureUnit")] string TemperatureUnit,
        [property: JsonPropertyName("detailedForecast")] string DetailedForecast);

    private record AlertResponse(
        [property: JsonPropertyName("features")] List<AlertFeature> Features);

    private record AlertFeature(
        [property: JsonPropertyName("properties")] AlertProperties Properties);

    private record AlertProperties(
        [property: JsonPropertyName("event")] string Event,
        [property: JsonPropertyName("headline")] string Headline);
}

using McpServer;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;

var builder = Host.CreateApplicationBuilder(args);

builder.Services
    .AddMcpServer()
    .WithStdioServerTransport()
    .WithToolsFromAssembly();

// Register a named HttpClient that the DI container injects into WeatherTools.
builder.Services.AddHttpClient<WeatherTools>(client =>
{
    client.BaseAddress = new Uri("https://api.weather.gov/");
    client.DefaultRequestHeaders.UserAgent.ParseAdd("mcp-weather-server/1.0");
});

await builder.Build().RunAsync();

